package dev.aster.charts;

import android.graphics.*;
import org.json.*;

/** New named study APIs over actual Java/JNI values, with no eval or URL load. */
final class StudyVerification {
    private final JSONArray checks=new JSONArray();
    private void check(boolean value,String reason){if(!value)throw new AssertionError(reason);checks.put(reason);}
    private boolean unavailable(JSONObject value)throws JSONException {return value.length()==3&&value.has("value")&&value.has("sourceIndex")&&value.has("sourceTime")&&value.isNull("value")&&value.isNull("sourceIndex")&&value.isNull("sourceTime");}
    private JSONObject inspect(AsterEngine engine)throws JSONException{return (JSONObject)engine.command("inspect");}
    JSONObject run(AsterEngine engine,AsterChartView view)throws Exception {
        String original=inspect(engine).toString();JSONObject shared=(JSONObject)engine.invoke("nativeStudyVerification");check(shared.getInt("passed")>0&&shared.getInt("passed")==shared.getJSONArray("checks").length(),"Actual QuickJS shared independent study checks");check(original.equals(inspect(engine).toString()),"Shared study verification preserves visible model");
        engine.invoke("nativeInit",0,new JSONObject().put("panels",new JSONArray().put(new JSONObject().put("id","price")).put(new JSONObject().put("id","volume"))).put("series",new JSONArray().put(new JSONObject().put("id","price").put("type","candles").put("panel","price"))));
        long time=1700000000000L;int[] closes={10,11,9,9,12},volumes={2,3,5,7,11};JSONArray bars=new JSONArray();for(int i=0;i<5;i++)bars.put(new JSONObject().put("time",time+i*60000L).put("open",closes[i]).put("high",closes[i]+1).put("low",closes[i]-1).put("close",closes[i]).put("volume",volumes[i]));engine.setData(bars);
        JSONArray names=engine.registerIndicatorModule("aster.volume-direction",1);check(names.length()==1&&names.getString(0).equals("aster.volume-direction@1/pressure"),"Java named module registration returns canonical export");
        JSONObject outputs=engine.addIndicator("java-pressure",names.getString(0),new JSONObject().put("factor",.5).put("shift",-1));check(outputs.getJSONArray("outputs").toString().equals("[\"signed\",\"cumulative\"]"),"Java module output metadata");
        JSONArray signed=(JSONArray)engine.command("indicatorValues","java-pressure","signed"),cumulative=(JSONArray)engine.command("indicatorValues","java-pressure","cumulative");double[] expectedSigned={0,1.5,-2.5,0,5.5},expectedCumulative={0,1.5,-1,-1,4.5};for(int i=0;i<5;i++){check(signed.getDouble(i)==expectedSigned[i],"Independent signed proxy literal index"+i);check(cumulative.getDouble(i)==expectedCumulative[i],"Independent cumulative proxy literal index"+i);}
        engine.command("addAxis",new JSONObject().put("id","java-study-axis").put("panel","volume"));engine.addSeries(new JSONObject().put("id","java-pressure-series").put("panel","volume").put("axisId","java-study-axis").put("type","histogram").put("indicator","java-pressure").put("output","signed"));
        final int[] notices={0};Runnable observer=()->notices[0]++;engine.addChangeListener(observer);
        String saved;try{long revision=engine.revision();saved=engine.saveStudies();JSONObject raw=engine.indicatorValueAt("java-pressure","signed",2,new JSONObject().put("mode","raw")),plot=engine.indicatorValueAt("java-pressure","signed",1,new JSONObject().put("mode","plot").put("asOfIndex",3));check(raw.getDouble("value")==-2.5&&raw.getInt("sourceIndex")==2&&raw.getLong("sourceTime")==time+120000L,"Java raw value retains exact source index/time");check(raw.toString().equals(plot.toString()),"Java negative plot offset resolves original source record");check(unavailable(engine.indicatorValueAt("java-pressure","signed",3,new JSONObject().put("mode","plot").put("asOfIndex",3))),"Unobserved shifted source hides value/index/time");check(unavailable(engine.indicatorValueAt("java-pressure","signed",4,new JSONObject().put("mode","raw").put("asOfIndex",3))),"As-of raw future record returns allnull");check(engine.revision()==revision&&notices[0]==0,"Study save/value reads preserve host revision and observers");}finally{engine.removeChangeListener(observer);}
        String before=engine.saveStudies();long revision=engine.revision();boolean rejected=false;try{engine.loadStudies(saved);}catch(IllegalStateException expected){rejected=true;}check(rejected&&before.equals(engine.saveStudies())&&engine.revision()==revision,"Duplicate import rejects atomically through Java facade");
        engine.removeIndicator("java-pressure");engine.command("removeAxis","java-study-axis");engine.addIndicator("java-existing","sma",new JSONObject().put("period",2));engine.addSeries(new JSONObject().put("id","java-existing-series").put("panel","price").put("type","line").put("indicator","java-existing"));String unrelated=engine.saveStudies();before=unrelated;revision=engine.revision();rejected=false;try{engine.loadStudies(saved);}catch(IllegalStateException expected){rejected=true;}check(rejected&&before.equals(engine.saveStudies())&&revision==engine.revision(),"Missing existing axis rejects without partial study merge");
        engine.command("addAxis",new JSONObject().put("id","java-study-axis").put("panel","volume"));JSONObject counts=engine.loadStudies(saved);check(counts.getInt("indicators")==1&&counts.getInt("series")==1&&new JSONObject(engine.saveStudies()).getJSONArray("indicators").length()==2,"Java additive study import adds requested definitions/bindings");check(engine.indicatorValueAt("java-existing","value",2).getDouble("value")==10,"Study import preserves existing SMA vector");engine.removeIndicator("java-pressure");check(unrelated.equals(engine.saveStudies()),"Imported study removal leaves unrelated configuration byteexact");
        JSONObject foreign=new JSONObject(saved);foreign.getJSONArray("series").getJSONObject(0).put("values",new JSONArray().put(1));before=engine.saveStudies();revision=engine.revision();rejected=false;try{engine.loadStudies(foreign.toString());}catch(IllegalStateException expected){rejected=true;}check(rejected&&before.equals(engine.saveStudies())&&revision==engine.revision(),"Serialized external values reject without replacing current studies");
        before=engine.saveStudies();rejected=false;try{engine.registerIndicatorModule("aster.volume-direction",2);}catch(IllegalStateException expected){rejected=true;}check(rejected&&before.equals(engine.saveStudies()),"Unknown module version does not change saved studies");
        java.util.concurrent.atomic.AtomicBoolean wrong=new java.util.concurrent.atomic.AtomicBoolean();Thread worker=new Thread(()->{try{engine.saveStudies();}catch(IllegalStateException expected){wrong.set(true);}catch(Exception unexpected){}});worker.start();worker.join(2000);check(wrong.get()&&!worker.isAlive(),"New study reader retains Java owner-thread guard");
        JSONObject demo=(JSONObject)engine.invoke("nativeAnalysisDemo");check(demo.getString("schema").equals("aster.analysis-demo")&&demo.getString("module").equals(names.getString(0)),"Native analysis demo uses linked module");JSONArray vwapOutputs=((JSONObject)engine.addIndicator("java-vwap-probe","vwap",new JSONObject().put("calendar",new JSONObject(demo.getString("setup")).getJSONArray("indicators").getJSONObject(0).getJSONObject("params").getString("calendar")).put("deviation",2))).getJSONArray("outputs");check(vwapOutputs.length()==5&&vwapOutputs.getString(0).equals("value")&&vwapOutputs.getString(1).equals("upper")&&vwapOutputs.getString(2).equals("lower"),"Java session VWAP exposes bands/deviation/volume outputs");engine.removeIndicator("java-vwap-probe");
        float density=view.getResources().getDisplayMetrics().density;view.fire("nativeResize",view.getWidth()/density,view.getHeight()/density);engine.invoke("nativePointer","move",0,view.getWidth()/density*.5,view.getHeight()/density*.3);
        JSONObject rich=(JSONObject)engine.invoke("nativeAccessibility",true);String text=(String)engine.invoke("nativeAccessibilityText",true,"android");check(text.equals(rich.getString("readout")),"String accessibility bridge is byteexact rich readout");Bitmap bitmap=Bitmap.createBitmap(view.getWidth(),view.getHeight(),Bitmap.Config.ARGB_8888);try{view.draw(new Canvas(bitmap));}finally{bitmap.recycle();}check(view.lastError==null&&text.contentEquals(view.getContentDescription()),"Actual View draw uses current complete string readout");
        return new JSONObject().put("passed",checks.length()).put("checks",checks).put("shared",shared).put("setup",saved).put("analysisDemo",demo).put("accessibilityText",text).put("physicalDevice",false).put("inputScope","Direct public Java SDK/JNI and offscreen attached View.draw; no OS touch injection, async eval or URL module load. Close-direction volume proxy is not bid/ask delta.");
    }
}
